import * as T from './vendor/three.module.js';
const {W,H,hubs}=globalThis.FieldPhysics;
export class FieldView{
 constructor(canvas){this.canvas=canvas;this.mode='orbit';this.theta=0;this.phi=.89;this.distance=18.5;this.scene=new T.Scene();this.scene.background=new T.Color('#202a25');this.camera=new T.PerspectiveCamera(42,1,.1,120);try{this.renderer=new T.WebGLRenderer({canvas,antialias:true});}catch(error){document.getElementById('hint').textContent='3D rendering needs WebGL. Enable hardware acceleration or try another browser.';throw error;}this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.25;this.scene.add(new T.HemisphereLight(0xd8edff,0x46503b,2.5));let sun=new T.DirectionalLight(0xfff4dc,3);sun.position.set(-6,16,6);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-13,right:13,top:10,bottom:-10,near:.1,far:40});sun.shadow.bias=-.0005;this.scene.add(sun);this.buildField();this.robot=new T.Group();this.scene.add(this.robot);this.ballGeometry=new T.SphereGeometry(.075,12,8);this.ballMaterial=this.material('#f5ce45');this.ballMeshes=[];this.aimLine=new T.Line(new T.BufferGeometry(),new T.LineDashedMaterial({color:0xd0ed93,dashSize:.12,gapSize:.08,transparent:true,opacity:.7}));this.scene.add(this.aimLine);this.pointer=null;canvas.addEventListener('pointerdown',e=>{if(this.mode!=='orbit')return;this.pointer={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!this.pointer)return;this.theta-=(e.clientX-this.pointer.x)*.006;this.phi=Math.max(.25,Math.min(1.45,this.phi+(e.clientY-this.pointer.y)*.005));this.pointer={x:e.clientX,y:e.clientY};});for(let ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,()=>this.pointer=null);canvas.addEventListener('wheel',e=>{e.preventDefault();this.distance=Math.max(8,Math.min(32,this.distance+e.deltaY*.015));},{passive:false});}
 material(color,options={}){return new T.MeshStandardMaterial({color,roughness:.75,metalness:.1,...options});}
 box(w,h,d,x,y,z,color,parent=this.scene){let mesh=new T.Mesh(new T.BoxGeometry(w,h,d),this.material(color));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
 cylinder(rt,rb,h,x,y,z,color,parent=this.scene){let mesh=new T.Mesh(new T.CylinderGeometry(rt,rb,h,24),this.material(color));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
 label(value,x,z,color,size=1){let c=document.createElement('canvas');c.width=768;c.height=96;let ctx=c.getContext('2d');ctx.font='600 42px sans-serif';ctx.fillStyle=color;ctx.textAlign='center';ctx.fillText(value,384,62);let tex=new T.CanvasTexture(c),mesh=new T.Mesh(new T.PlaneGeometry(size*4,size*.5),new T.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false}));mesh.rotation.x=-Math.PI/2;mesh.position.set(x,.016,z);this.scene.add(mesh);}
 buildField(){this.box(W+.5,.18,H+.5,0,-.15,0,'#161e1b');this.box(W,.04,H,0,-.04,0,'#485247');this.box(4.5,.015,H,-W/2+2.25,-.01,0,'#3a5263');this.box(4.5,.015,H,W/2-2.25,-.01,0,'#654a43');this.gridGroup=new T.Group();this.scene.add(this.gridGroup);for(let x=-W/2;x<=W/2;x+=.5)this.box(.008,.003,H,x,.003,0,'#5b6558',this.gridGroup);for(let z=-H/2;z<=H/2;z+=.5)this.box(W,.003,.008,0,.003,z,'#5b6558',this.gridGroup);
 for(let z of [-H/2,H/2]){this.box(W+.25,.1,.09,0,.48,z,'#99a29a');let glass=this.box(W,.42,.035,0,.22,z,'#8eabb4');glass.material.transparent=true;glass.material.opacity=.12;for(let x=-W/2;x<=W/2;x+=1.35)this.box(.04,.5,.045,x,.23,z,'#858d88');}for(let x of [-W/2,W/2]){this.box(.1,.55,H,x,.25,0,x<0?'#3c6499':'#9d514a');for(let z of [-2.7,0,2.7])this.box(.12,.8,2.4,x,.9,z,'#324039');}
 for(let h of hubs){let x=h.x-W/2,color=h.alliance==='blue'?'#568eed':'#dd7868';this.box(.06,.014,H,x,.012,0,color);let group=new T.Group();this.scene.add(group);this.box(1.32,.25,1.32,x,.125,0,'#5c6660',group);for(let dx of [-.53,.53])for(let dz of [-.53,.53])this.box(.09,1.6,.09,x+dx,.9,dz,'#b9bdb3',group);for(let z of [-.62,.62])this.box(1.25,.5,.06,x,1.25,z,color,group);for(let dx of [-.62,.62])this.box(.06,.5,1.25,x+dx,1.25,0,color,group);let torus=new T.Mesh(new T.TorusGeometry(.5,.055,8,40),this.material('#d5d9c5'));torus.rotation.x=Math.PI/2;torus.position.set(x,1.8,0);torus.castShadow=true;group.add(torus);let basket=new T.Mesh(new T.CylinderGeometry(.5,.3,.48,24,1,true),this.material('#343e36',{side:T.DoubleSide}));basket.position.set(x,1.55,0);group.add(basket);
 for(let sign of [-1,1]){let ramp=this.box(.9,.15,2.15,x,.075,sign*2,'#a99b65');for(let k=-.33;k<.4;k+=.16)this.box(.025,.025,2.12,x+k,.16,sign*2,'#d4c18a');let tz=sign*(H/2-.4);for(let dx of [-.62,.62])this.box(.06,.73,.65,x+dx,.365,tz,'#b4b9ad');this.box(1.3,.08,.75,x,.77,tz,color);}
 let tx=h.alliance==='blue'?-W/2+.38:W/2-.38;for(let dz of [-.6,.6])this.box(.08,1.55,.08,tx,.775,dz,'#bec2b6');for(let y=.2;y<1.6;y+=.28)this.box(.08,.05,1.2,tx,y,0,'#c9ccbe');}
 this.label('BLUE ALLIANCE',-6.1,3.45,'#90baff',.65);this.label('RED ALLIANCE',6.1,3.45,'#ffb1a0',.65);this.label('MID-ATLANTIC  /  FIELD LAB',0,3.45,'#a2b293',.75);this.label('NEUTRAL ZONE',0,-3.5,'#a2b293',.65);
 }
 rebuildRobot(c){while(this.robot.children.length){let child=this.robot.children[0];child.traverse(o=>{o.geometry?.dispose();if(o.material){o.material.map?.dispose();o.material.dispose();}});this.robot.remove(child);}let color=c.alliance==='blue'?'#568eed':'#dd7868',l=c.length,w=c.width;this.box(l,.18,w,0,.2,0,color,this.robot);this.box(l*.8,.09,w*.8,0,.34,0,'#9da59e',this.robot);this.box(l*.64,.3,w*.65,-.05,.51,0,'#263e38',this.robot);for(let x of [-l*.32,l*.32])for(let z of [-w*.38,w*.38]){let wheel=this.cylinder(.1,.1,.09,x,.13,z,'#101513',this.robot);wheel.rotation.x=Math.PI/2;}this.intakeBar=this.cylinder(.065,.065,w*.85,l/2+.06,.15,0,'#b5d983',this.robot);this.intakeBar.rotation.x=Math.PI/2;this.turret=new T.Group();this.turret.position.y=.67;this.robot.add(this.turret);this.cylinder(.18,.18,.08,0,0,0,'#b7bcac',this.turret);let barrel=this.box(.36,.13,.23,.16,.08,0,'#d3d8bc',this.turret);barrel.rotation.z=.35;let cv=document.createElement('canvas');cv.width=256;cv.height=128;let ct=cv.getContext('2d');ct.fillStyle=color;ct.fillRect(0,0,256,128);ct.fillStyle='white';ct.textAlign='center';ct.font='bold 66px sans-serif';ct.fillText(c.team==='custom'?'FMA':c.team,128,88);let tex=new T.CanvasTexture(cv);for(let sign of [-1,1]){let tag=new T.Mesh(new T.PlaneGeometry(l*.7,.15),new T.MeshBasicMaterial({map:tex}));tag.position.set(0,.22,sign*(w/2+.002));if(sign<0)tag.rotation.y=Math.PI;this.robot.add(tag);}this.robotKey=[c.width,c.length,c.alliance,c.team].join('|');}
 setCamera(mode){this.mode=mode;this.pointer=null;}
 resize(){let w=this.canvas.clientWidth,h=this.canvas.clientHeight;if(!w||!h)return;this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();}
 draw(sim,grid){let c=sim.config,r=sim.robot;if(this.robotKey!==[c.width,c.length,c.alliance,c.team].join('|'))this.rebuildRobot(c);this.gridGroup.visible=grid;let x=r.x-W/2,z=r.y-H/2;this.robot.position.set(x,0,z);this.robot.rotation.y=-r.a;this.intakeBar.material.color.set(sim.intake?'#d0ed93':'#596350');let aim=c.autoAim?Math.atan2(sim.target.y-r.y,sim.target.x-r.x):r.a;this.turret.rotation.y=r.a-aim;
 while(this.ballMeshes.length<sim.balls.length){let mesh=new T.Mesh(this.ballGeometry,this.ballMaterial);mesh.castShadow=true;this.scene.add(mesh);this.ballMeshes.push(mesh);}this.ballMeshes.forEach((mesh,i)=>{let b=sim.balls[i];mesh.visible=!!b;if(b)mesh.position.set(b.x-W/2,b.z,b.y-H/2);});
 let points=[];for(let i=0;i<=24;i++){let t=i/24;points.push(new T.Vector3(x+Math.cos(aim)*t*2.2,.68+Math.sin(t*Math.PI)*.7,z+Math.sin(aim)*t*2.2));}this.aimLine.geometry.dispose();this.aimLine.geometry=new T.BufferGeometry().setFromPoints(points);this.aimLine.computeLineDistances();this.aimLine.visible=sim.inventory>0;
 if(this.mode==='follow'){this.camera.position.lerp(new T.Vector3(x-3.5,4.8,z+5),.08);this.camera.lookAt(x,.2,z);}else if(this.mode==='top'){this.camera.position.set(0,22,.01);this.camera.lookAt(0,0,0);}else{let dist=this.distance*(this.camera.aspect<1.3?1.2:1);this.camera.position.set(Math.sin(this.theta)*Math.cos(this.phi)*dist,Math.sin(this.phi)*dist,Math.cos(this.theta)*Math.cos(this.phi)*dist);this.camera.lookAt(0,0,0);}this.renderer.render(this.scene,this.camera);}
}
